    # Initialize the table with empty cells
    table = [['' for _ in range(m)] for _ in range(n)]

    # Function to check if a region is a square
    def is_square(x1, y1, x2, y2):
        side = (x2 - x1 + 1)
        if (x2 - x1 + 1) != (y2 - y1 + 1):
            return False
        for i in range(x1, x2 + 1):
            for j in range(y1, y2 + 1):
                if table[i][j] != table[x1][y1]:
                    return False
        return True

    # Function to paint the table
    def paint_table(x, y, color):
        table[x][y] = color
        # Try to expand the square in all four directions
        for side in range(1, min(n - x, m - y) + 1):
            if is_square(x, y, x + side - 1, y + side - 1):
